<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Data pemohon</h1><p>Lihat akun pemohon dan buka riwayat pengajuannya dari satu daftar.</p></div></div>
<form class="card filter-card" method="get" action="<?= site_url('petugas/pemohon') ?>"><div class="search-bar" style="margin:0"><input type="search" name="q" value="<?= e($query) ?>" placeholder="Cari nama, email, atau instansi" aria-label="Cari pemohon"><button class="button primary" type="submit">Cari</button></div></form>
<section class="card table-card"><div class="filter-results"><span><strong><?= count($applicants) ?></strong> pemohon ditampilkan<?= count($applicants) >= 100 ? ' (maksimal 100 terbaru)' : '' ?></span><a href="<?= site_url('petugas/pemohon') ?>">Hapus pencarian</a></div>
<?php if ($applicants): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama pemohon</th><th>Instansi</th><th>Kontak</th><th>Permohonan</th><th>Terakhir masuk</th><th></th></tr></thead><tbody><?php foreach ($applicants as $person): ?><tr><td data-label="Pemohon"><strong><?= e($person->full_name) ?></strong><small><?= $person->account_status === 'active' ? 'Akun aktif' : 'Akun nonaktif' ?></small></td><td data-label="Instansi"><?= e($person->organization_name ?: '—') ?></td><td data-label="Kontak"><?= e($person->email) ?><small><?= e($person->phone) ?></small></td><td data-label="Permohonan"><?= (int) $person->request_count ?></td><td data-label="Terakhir"><?= $person->last_submission ? e(tanggal_id($person->last_submission)) : '—' ?></td><td data-label="Aksi"><a class="table-link" href="<?= site_url('petugas/permohonan?pemohon=' . $person->id) ?>">Riwayat →</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty"><strong>Belum ada pemohon yang cocok</strong>Coba kata kunci lain.</div><?php endif; ?></section>
